"""Alembic environment.

Always runs against an engine handed in by ``run_migrations`` -- the app's engine in
production, a temporary file in tests -- so there is one migration path and no second
way to create a schema. ``render_as_batch`` is on because SQLite cannot ALTER a
column in place; Alembic rebuilds the table instead, which keeps later migrations
portable to Postgres (ADR-005).
"""

from __future__ import annotations

from alembic import context

from services.production.db.models import Base

target_metadata = Base.metadata

# Autogenerated migrations render custom types as "dbtypes.X" (user_module_prefix
# below). Add "import services.production.db.types as dbtypes" to a new migration,
# and replace any dbtypes.EnumText(...) with sa.String(...): the stored form is a
# string, and the enum conversion belongs to the model layer, not the DDL.


def run_migrations_online() -> None:
    connectable = context.config.attributes.get("connection")
    if connectable is None:
        raise RuntimeError(
            "no engine supplied; drive migrations through "
            "services.production.db.session.run_migrations"
        )
    with connectable.connect() as connection:
        context.configure(
            connection=connection,
            target_metadata=target_metadata,
            render_as_batch=True,
            compare_type=True,
            user_module_prefix="dbtypes.",
        )
        with context.begin_transaction():
            context.run_migrations()


run_migrations_online()
